/**
 * VegMitra Traffic Management System - Mock / Demo Data Service
 * 
 * Provides an interactive, clearly-labeled simulation engine with realistic
 * traffic flows, density hysteresis, minimum green hold countdowns, and
 * scenario transitions.
 * 
 * IMPORTANT: All data generated by this service is clearly marked as simulated
 * and must not be confused with real YOLOv8 backend detections.
 */

import { RoadName, RawTrafficStatePayload, DemoScenario } from '../types/traffic';
import { ALL_ROADS } from './trafficAdapter';

export const DEMO_SCENARIOS: DemoScenario[] = [
  {
    id: 'balanced',
    name: 'Normal Urban Traffic (Balanced)',
    description: 'Steady moderate traffic across all four approaches with normal adaptive rotation.',
    counts: { North: 3, South: 4, East: 3, West: 2 },
    smoothedCounts: { North: 3.2, South: 3.8, East: 3.1, West: 2.4 },
    densities: { North: 10.7, South: 12.7, East: 10.3, West: 8.0 },
    selectedRoad: 'South',
    holdTime: 7.5,
    emergencyActive: false
  },
  {
    id: 'peak_morning',
    name: 'Morning Commute (East Corridor Heavy)',
    description: 'Inbound East & South corridors experiencing heavy arterial commuter volume.',
    counts: { North: 2, South: 8, East: 14, West: 3 },
    smoothedCounts: { North: 2.1, South: 7.6, East: 13.5, West: 2.9 },
    densities: { North: 7.0, South: 25.3, East: 45.0, West: 9.7 },
    selectedRoad: 'East',
    holdTime: 12.0,
    emergencyActive: false
  },
  {
    id: 'peak_evening',
    name: 'Evening Commute (West & North Heavy)',
    description: 'Outbound traffic peak creating elevated density on West and North corridors.',
    counts: { North: 9, South: 3, East: 4, West: 16 },
    smoothedCounts: { North: 8.7, South: 3.1, East: 3.8, West: 15.2 },
    densities: { North: 29.0, South: 10.3, East: 12.7, West: 50.7 },
    selectedRoad: 'West',
    holdTime: 10.0,
    emergencyActive: false
  },
  {
    id: 'emergency_ambulance',
    name: 'Emergency Priority (Ambulance on South)',
    description: 'Simulates high-priority emergency preemption overriding standard hysteresis scheduling.',
    counts: { North: 4, South: 6, East: 7, West: 3 },
    smoothedCounts: { North: 4.0, South: 6.2, East: 6.9, West: 3.1 },
    densities: { North: 13.3, South: 20.7, East: 23.0, West: 10.3 },
    selectedRoad: 'South',
    holdTime: 14.5,
    emergencyActive: true,
    emergencyRoad: 'South',
    emergencyClass: 'ambulance'
  }
];

export class MockTrafficSimulationEngine {
  private currentScenarioIndex: number = 0;
  private currentScenario: DemoScenario;
  private frameCounter: number = 100;
  private holdRemaining: number = 8.0;
  private minGreenDuration: number = 8.0;
  private switchThreshold: number = 2.0; // 2 percentage point hysteresis
  private currentGreenRoad: RoadName = 'South';
  private simulatedEmergency: boolean = false;
  private simulatedEmergencyRoad: RoadName = 'South';
  private capacityPerRoad: number = 30; // standard capacity in VegMitra detector

  // State caches
  private currentCounts: Record<RoadName, number>;
  private smoothedCounts: Record<RoadName, number>;
  private densities: Record<RoadName, number>;

  constructor() {
    this.currentScenario = { ...DEMO_SCENARIOS[0] };
    this.currentCounts = { ...this.currentScenario.counts };
    this.smoothedCounts = { ...this.currentScenario.smoothedCounts };
    this.densities = { ...this.currentScenario.densities };
    this.currentGreenRoad = this.currentScenario.selectedRoad;
    this.holdRemaining = this.currentScenario.holdTime;
  }

  public setScenario(scenarioId: string) {
    const found = DEMO_SCENARIOS.find(s => s.id === scenarioId);
    if (found) {
      this.currentScenario = { ...found };
      this.currentCounts = { ...found.counts };
      this.smoothedCounts = { ...found.smoothedCounts };
      this.densities = { ...found.densities };
      this.currentGreenRoad = found.selectedRoad;
      this.holdRemaining = found.holdTime;
      this.simulatedEmergency = found.emergencyActive;
      this.simulatedEmergencyRoad = (found.emergencyRoad as RoadName) || 'South';
    }
  }

  public toggleSimulatedEmergency(road: RoadName = 'South'): boolean {
    this.simulatedEmergency = !this.simulatedEmergency;
    this.simulatedEmergencyRoad = road;
    if (this.simulatedEmergency) {
      this.currentGreenRoad = road;
      this.holdRemaining = 15.0; // Extended emergency clear window
    }
    return this.simulatedEmergency;
  }

  /**
   * Advances the simulation by dt seconds (typically 0.5s or 1.0s).
   */
  public tick(dt: number = 1.0): RawTrafficStatePayload {
    this.frameCounter += Math.round(dt * 25); // Simulate 25 FPS video pipeline
    const timestamp = Date.now() / 1000;

    // Small stochastic noise representing real vehicle movement
    for (const r of ALL_ROADS) {
      const base = this.currentScenario.counts[r];
      // Random delta between -1 and +1
      const delta = (Math.random() > 0.6 ? 1 : 0) - (Math.random() > 0.6 ? 1 : 0);
      const newCount = Math.max(0, Math.min(25, base + delta));
      this.currentCounts[r] = newCount;

      // 10-frame exponential moving average update
      const alpha = 0.15;
      this.smoothedCounts[r] = Number((this.smoothedCounts[r] * (1 - alpha) + newCount * alpha).toFixed(1));

      // Density calculation: smoothed_count / capacity * 100
      this.densities[r] = Number(Math.min(100, (this.smoothedCounts[r] / this.capacityPerRoad) * 100).toFixed(1));
    }

    // Decrement minimum green hold timer
    this.holdRemaining = Math.max(0, this.holdRemaining - dt);

    // Emergency Preemption Override
    if (this.simulatedEmergency) {
      this.currentGreenRoad = this.simulatedEmergencyRoad;
      if (this.holdRemaining <= 0) {
        this.holdRemaining = 10.0;
      }
    } else if (this.holdRemaining <= 0) {
      // Find approach with highest density
      let bestRoad: RoadName = this.currentGreenRoad;
      let highestDensity = -1;

      for (const r of ALL_ROADS) {
        if (this.densities[r] > highestDensity) {
          highestDensity = this.densities[r];
          bestRoad = r;
        }
      }

      const currentDensity = this.densities[this.currentGreenRoad];

      // Hysteresis check: new road must exceed current road density by switchThreshold
      if (bestRoad !== this.currentGreenRoad && (highestDensity - currentDensity >= this.switchThreshold)) {
        this.currentGreenRoad = bestRoad;
        this.holdRemaining = this.minGreenDuration;
      } else if (highestDensity <= 0) {
        // Round robin if empty
        const nextIdx = (ALL_ROADS.indexOf(this.currentGreenRoad) + 1) % ALL_ROADS.length;
        this.currentGreenRoad = ALL_ROADS[nextIdx];
        this.holdRemaining = this.minGreenDuration;
      }
    }

    const totalVehicles = Object.values(this.currentCounts).reduce((a, b) => a + b, 0);

    return {
      timestamp,
      frame_index: this.frameCounter,
      counts: { ...this.currentCounts },
      smoothed_counts: { ...this.smoothedCounts },
      density: { ...this.densities },
      selected_green_road: this.currentGreenRoad,
      emergency_active: this.simulatedEmergency,
      emergency_road: this.simulatedEmergency ? this.simulatedEmergencyRoad : null,
      emergency_class: this.simulatedEmergency ? 'ambulance' : null,
      total_vehicles: totalVehicles,
      green_hold_remaining: Number(this.holdRemaining.toFixed(1))
    };
  }
}
